async function initMap(){syncViewportMetrics();await loadKakao();const fallback=new kakao.maps.LatLng(37.5665,126.9780);state.map=new kakao.maps.Map($('#map'),{center:fallback,level:5});state.map.setDraggable(true);state.map.setZoomable(true);state.placesService=new kakao.maps.services.Places(state.map);kakao.maps.event.addListener(state.map,'click',handleMapClick);kakao.maps.event.addListener(state.map,'dragstart',handleMapDragStart);kakao.maps.event.addListener(state.map,'dragend',handleMapDragEnd);kakao.maps.event.addListener(state.map,'zoom_start',handleMapZoomStart);kakao.maps.event.addListener(state.map,'zoom_changed',handleMapZoomChanged);kakao.maps.event.addListener(state.map,'bounds_changed',handleMapBoundsChanged);kakao.maps.event.addListener(state.map,'idle',handleMapIdle);await locate(true).catch(()=>toast('현재 위치를 확인할 수 없습니다.'));renderScreen('map',false)}
