function cancelNavigationRoutePreview(navigateBack=true){const draft=state.navigationRouteDraft;if(!draft)return false;clearRoutes();state.routes=draft.original.routes;state.selectedRoute=draft.original.selectedRoute;state.nav.follow=draft.original.follow;state.navigationRouteDraft=null;state.navigationRouteOriginal=null;state.navigationSearch=false;state.navigationSearchMode=null;state.navSearchViewport=null;drawNavigationRoute();if(draft.original.follow)initializeNavigationCamera();else{setNavigationFollow(false);if(Number.isFinite(draft.original.level))setNavigationLevel(draft.original.level);if(draft.original.center)state.map?.setCenter?.(draft.original.center)}if(navigateBack)history.back();return true}
function replaceNavigationDestination(destination){return beginNavigationRoutePreview('destination',destination)}
function addNavigationWaypoint(place){return beginNavigationRoutePreview('waypoint',place)}
function finishNavigation(arrived=false){cancelNavigationReturn();if(state.nav.watchId!=null){navigator.geolocation.clearWatch(state.nav.watchId);state.nav.watchId=null}const duration=activeRideDuration();state.nav.averageSpeed=duration>0?state.nav.distance/(duration/1000):0;$('#summaryDistance').textContent=fmtKm(state.nav.distance);$('#summaryDuration').textContent=`${Math.max(1,Math.round(duration/60000))}분`;$('#summaryAverageSpeed').textContent=`${(state.nav.averageSpeed*3.6).toFixed(1)} km/h`;$('#summaryMaxSpeed').textContent=`${(state.nav.maxSpeed*3.6).toFixed(1)} km/h`;state.nav.summary={distance:state.nav.distance,duration,averageSpeed:state.nav.averageSpeed,maxSpeed:state.nav.maxSpeed,departure:state.departure,destination:state.destination,routeMode:state.routes[state.selectedRoute]?.routeMode,arrived,endedAt:new Date().toISOString()};$('#navMenu').classList.add('hidden');$('#saveModal').classList.remove('hidden')}
function resetAfterRide(){cancelNavigationReturn();finishNavigationCameraMove();if(state.nav.watchId!=null)navigator.geolocation.clearWatch(state.nav.watchId);clearRoutes();state.routes=[];state.selectedRoute=null;state.departure=null;state.waypoints=[];state.destination=null;state.selectedPlace=null;state.editingEndpoint=null;state.editingWaypointIndex=null;state.nav=createNavState();$('#saveModal').classList.add('hidden');renderScreen('map');locate(true).catch(()=>{})}
function saveRide(){try{if(profileRepository&&activeProfileId)profileRepository.prependRide(activeProfileId,state.nav.summary);else{let rides=[];try{rides=JSON.parse(localStorage.getItem('ridemate_rides')||'[]');if(!Array.isArray(rides))rides=[]}catch{rides=[]}rides.unshift(state.nav.summary);localStorage.setItem('ridemate_rides',JSON.stringify(rides.slice(0,100)))}toast('주행 기록을 저장했습니다.');resetAfterRide()}catch{toast('저장하지 못했습니다. 저장공간을 확인해주세요.',3000)}}

function profileAvatarMarkup(avatar){const iconId=avatar?.type==='icon'&&PROFILE_AVATARS[avatar.iconId]?avatar.iconId:'rider';return`<span class="profile-avatar" aria-hidden="true">${PROFILE_AVATARS[iconId]}</span>`}
function renderMainMenuProfile(){const profile=profileRepository?.getProfiles().find(item=>item.id===activeProfileId);if(!profile)return;const iconId=profile.avatar?.type==='icon'&&PROFILE_AVATARS[profile.avatar.iconId]?profile.avatar.iconId:'rider';$('#mainMenuProfileAvatar').textContent=PROFILE_AVATARS[iconId];$('#mainMenuProfileName').textContent=profile.name}
function openMainMenu(){const menu=$('#mainMenu');if(!menu.classList.contains('hidden'))return;renderMainMenuProfile();menu.classList.remove('hidden');menu.setAttribute('aria-hidden','false');history.pushState({...history.state,screen:state.screen,mainMenu:true},'')}
function closeMainMenu(fromHistory=false){const menu=$('#mainMenu');if(menu.classList.contains('hidden'))return;menu.classList.add('hidden');menu.setAttribute('aria-hidden','true');if(!fromHistory&&history.state?.mainMenu){mainMenuHistoryClosing=true;history.back()}}
function renderVoiceTest(){const synthesis=window.speechSynthesis,allVoices=synthesis?[...synthesis.getVoices()]:[];koreanSpeechVoices=allVoices.filter(voice=>String(voice.lang||'').toLowerCase().startsWith('ko'));$('#voiceCount').textContent=`사용 가능한 한국어 음성: ${koreanSpeechVoices.length}개`;$('#voiceEmpty').classList.toggle('hidden',koreanSpeechVoices.length>0);const list=$('#voiceList');list.innerHTML=koreanSpeechVoices.map((voice,index)=>`<article class="voice-item"><strong>${esc(voice.name)}</strong><small>${esc(voice.lang)}</small><small>localService: ${Boolean(voice.localService)}</small><small>default: ${Boolean(voice.default)}</small><button type="button" data-voice-index="${index}">듣기</button></article>`).join('');list.querySelectorAll('[data-voice-index]').forEach(button=>button.onclick=()=>speakVoice(Number(button.dataset.voiceIndex)));$('#allVoiceCount').textContent=`사용 가능한 전체 음성: ${allVoices.length}개`;$('#allVoiceList').innerHTML=allVoices.map(voice=>`<article class="voice-item voice-item-readonly"><strong>${esc(voice.name)}</strong><small>${esc(voice.lang)}</small><small>localService: ${Boolean(voice.localService)}</small><small>default: ${Boolean(voice.default)}</small></article>`).join('')}
function speakVoice(index){const synthesis=window.speechSynthesis,voice=koreanSpeechVoices[index];if(!synthesis||!voice||typeof window.SpeechSynthesisUtterance!=='function')return;synthesis.cancel();const utterance=new SpeechSynthesisUtterance(VOICE_TEST_SENTENCE);utterance.voice=voice;utterance.lang='ko-KR';synthesis.speak(utterance)}
function speakDefaultKorean(){const synthesis=window.speechSynthesis;if(!synthesis||typeof window.SpeechSynthesisUtterance!=='function')return;synthesis.cancel();const utterance=new SpeechSynthesisUtterance(VOICE_TEST_SENTENCE);utterance.lang='ko-KR';synthesis.speak(utterance)}
function openVoiceTest(){closeMainMenu(true);renderVoiceTest();const screen=$('#voiceTestScreen');screen.classList.remove('hidden');screen.setAttribute('aria-hidden','false');history.replaceState({...history.state,mainMenu:false,voiceTest:true},'','#voice-test')}
function closeVoiceTest(fromHistory=false){const screen=$('#voiceTestScreen');if(screen.classList.contains('hidden'))return;window.speechSynthesis?.cancel();screen.classList.add('hidden');screen.setAttribute('aria-hidden','true');if(!fromHistory&&history.state?.voiceTest){voiceTestHistoryClosing=true;history.back()}}
function renderProfileSelection(model){
  const grid=$('#profileGrid'),empty=$('#profileEmptyState'),selectButton=$('#profileSelectButton');
  if(!grid||!empty||!selectButton)return;
  empty.textContent=model.emptyMessage;
  empty.classList.toggle('hidden',!model.emptyMessage);
  grid.innerHTML=model.profiles.map(profile=>{const selected=profile.id===model.selectedProfileId;return`<div class="profile-card-wrapper"><button class="profile-select-control${selected?' selected':''}" type="button" data-profile-select="${esc(profile.id)}" aria-pressed="${selected}">${selected?'<span class="profile-selected-mark" aria-hidden="true">✓</span>':''}${profileAvatarMarkup(profile.avatar)}<strong>${esc(profile.name)}</strong><span class="profile-card-caption">라이딩을 함께 시작해요</span></button><button class="profile-manage-control" type="button" data-profile-manage="${esc(profile.id)}" aria-label="${esc(profile.name)} 프로필 관리">⋯</button></div>`}).join('')+`<button class="profile-add-card" id="profileAddCard" type="button"><span class="profile-plus-circle" aria-hidden="true">＋</span><strong>프로필 추가</strong></button>`;
  selectButton.disabled=!model.canSelect;
  grid.querySelectorAll('[data-profile-select]').forEach(button=>button.onclick=()=>profileController.selectProfile(button.dataset.profileSelect));
  grid.querySelectorAll('[data-profile-manage]').forEach(button=>button.onclick=()=>openProfileEditor(button.dataset.profileManage));
  $('#profileAddCard').onclick=()=>openProfileEditor();
}
function showProfileScreen(){activeProfileId=null;$('#profileScreen')?.classList.remove('hidden');$('#app')?.classList.add('hidden')}
function showMapScreen(){activeProfileId=profileSession.getSelectedProfileId();$('#profileScreen')?.classList.add('hidden');$('#app')?.classList.remove('hidden')}
function renderProfileAvatarChoices(selectedIconId='rider'){$('#profileAvatarChoices').innerHTML=Object.entries(PROFILE_AVATARS).map(([iconId,icon])=>`<label class="profile-avatar-option"><input type="radio" name="profileAvatar" value="${iconId}"${iconId===selectedIconId?' checked':''}><span aria-hidden="true">${icon}</span></label>`).join('')}
function openProfileEditor(profileId=null){
  editingProfileId=profileId;
  const profile=profileId?profileRepository.getProfiles().find(item=>item.id===profileId):null;
  $('#profileEditorTitle').textContent=profile?'프로필 수정':'프로필 추가';
  $('#profileNameInput').value=profile?.name||'';
  $('#profileEditorError').textContent='';
  renderProfileAvatarChoices(profile?.avatar?.iconId||'rider');
  $('#profileDeleteButton').classList.toggle('hidden',!profile);
  $('#profileEditor').classList.remove('hidden');
  setTimeout(()=>$('#profileNameInput').focus(),0);
}
function closeProfileEditor(){editingProfileId=null;$('#profileEditor').classList.add('hidden');$('#profileEditorError').textContent=''}
function wireProfileUi(){
  $('#profileAddTop').onclick=()=>openProfileEditor();
  $('#profileEditorCancel').onclick=closeProfileEditor;
  $('#profileEditorForm').onsubmit=event=>{event.preventDefault();const name=$('#profileNameInput').value,iconId=$('input[name="profileAvatar"]:checked')?.value||'rider';try{if(editingProfileId)profileController.updateProfile(editingProfileId,{name,avatar:{type:'icon',iconId}});else profileController.addProfile(name,{type:'icon',iconId});closeProfileEditor()}catch(error){$('#profileEditorError').textContent=error.message}};
  $('#profileDeleteButton').onclick=()=>{$('#profileEditor').classList.add('hidden');$('#profileDeleteConfirm').classList.remove('hidden')};
  $('#profileDeleteCancel').onclick=()=>{$('#profileDeleteConfirm').classList.add('hidden');$('#profileEditor').classList.remove('hidden')};
  $('#profileDeleteConfirmButton').onclick=()=>{if(editingProfileId)profileController.deleteProfile(editingProfileId);editingProfileId=null;$('#profileDeleteConfirm').classList.add('hidden');$('#profileEditor').classList.add('hidden')};
  $('#profileSelectButton').onclick=async()=>{const button=$('#profileSelectButton');if(button.disabled)return;button.disabled=true;try{await profileController.confirmSelection()}catch(error){button.disabled=false;globalThis.alert?.(`지도를 불러오지 못했습니다. ${error.message}`)}};
}
function bootProfileSelection(){
  const api=globalThis.RideMateProfiles;
  profileRepository=api.createProfileRepository(localStorage);
  profileRepository.initialize();
  profileSession=api.createProfileSession(profileRepository,{startMap:()=>initMap()});
  profileController=api.createProfileController(profileRepository,profileSession,{render:renderProfileSelection,showProfileScreen,showMapScreen});
  wireProfileUi();
  profileController.start();
}

